cat > /tmp/opencode/test-dispatcher.js <<'EOF'
const { deliver } = require('/workspace/src/dispatcher.js');

async function run(name, fn) {
  try { console.log(name, '=>', JSON.stringify(await fn())); }
  catch (e) { console.log(name, '=> THREW:', e.message); }
}

(async () => {
  // 1. Success on first try, event has id -> header passed
  await run('success', async () => {
    let calls = [];
    const io = { post: async (p, e, o) => { calls.push([p, o]); return { status: 200, body: 'ok' }; } };
    const res = await deliver(io, { id: 'evt-1', type: 'x' });
    console.log('   calls:', JSON.stringify(calls));
    return res;
  });

  // 2. 502 twice, then 200 -> retries with backoff, header stable across attempts
  await run('retry-502-then-ok', async () => {
    let n = 0;
    const headersSeen = [];
    const io = { post: async (p, e, o) => {
      n++;
      headersSeen.push(o && o.headers && o.headers['X-Event-Id']);
      if (n <= 2) return { status: 502, body: 'bad gateway' };
      return { status: 200, body: 'ok' };
    } };
    const res = await deliver(io, { id: 'evt-2', type: 'y' }, { maxRetries: 5, jitter: false });
    console.log('   attempts:', n, 'headers:', JSON.stringify(headersSeen));
    return res;
  });

  // 3. Always 502 -> throws after maxRetries+1 attempts
  await run('always-502', async () => {
    let n = 0;
    const io = { post: async () => { n++; return { status: 502 }; } };
    try {
      await deliver(io, { id: 'evt-3' }, { maxRetries: 2, jitter: false });
    } catch (e) {
      console.log('   attempts:', n, 'error:', e.message);
      return 'threw-as-expected';
    }
  });

  // 4. Network error (throws) twice, then success
  await run('throw-then-ok', async () => {
    let n = 0;
    const io = { post: async () => { n++; if (n <= 2) throw new Error('ECONNRESET'); return { status: 201 }; } };
    const res = await deliver(io, { id: 'evt-4' }, { maxRetries: 3, jitter: false });
    console.log('   attempts:', n);
    return res;
  });

  // 5. 4xx is not retried -> returns immediately
  await run('client-error-no-retry', async () => {
    let n = 0;
    const io = { post: async () => { n++; return { status: 400 }; } };
    const res = await deliver(io, { id: 'evt-5' }, { maxRetries: 3 });
    console.log('   attempts:', n);
    return res;
  });

  // 6. No id -> two-arg call preserved
  await run('no-id', async () => {
    let call = null;
    const io = { post: async (p, e, o) => { call = [p, arguments]; return { status: 200 }; } };
    await deliver(io, { type: 'no-id' });
    console.log('   callArgs: ', call);
    return 'ok';
  });
})();
EOF
